/**
 * Messages for the "offline" area.
 *
 * The offline fallback is generated by the hand-written worker in
 * `public/sw.js`, which has no build step and cannot import this module. The
 * strings below therefore mirror its two language blocks exactly: editing one
 * without the other leaves the worker and the dictionaries out of step.
 *
 * Flat, dotted keys. A key whose text differs by count is written as
 * "singular|plural" and rendered with `t(key, { count })`, which selects
 * the form with Intl.PluralRules for the active locale.
 */
export const offline = {
  "offline.title": "forte — offline",
  "offline.heading": "You are offline",
  "offline.body.network":
    "forte cannot reach the network right now, and this page was not saved for offline use.",
  "offline.body.workout":
    "A workout already in progress still works: log sets, edit them, and finish the workout. Everything is stored on this device and syncs the next time you are online.",
  "offline.retry": "Try again",
} as const;
